  "business_linkages": [],
  "business_linkage_gap": "現有資料只揭露分拆意向與集團層級的歷史回購。要判斷分拆對留存業務的獲利影響，仍需共享成本、分拆後費用負擔或雙方服務協議的資料。公告也未具名揭露受影響的供應商或客戶。",
  "hypotheses": [
    {
      "stance": "wait",
      "mechanism": "分拆須滿足後續條件並取得核准，董事會提出的 18 個月目標涵蓋 2025 年底之後。研究期內可先用執行進度檢驗時程假設。",
      "target": "FedEx Freight 分拆進度",
      "horizon": "2025-12-31",
      "catalyst": "FedEx 公布分拆條件、核准進度或修訂時程。",
      "prediction": "基準情境為截至 2025 年底，FedEx Freight 仍處於分拆準備階段。屆時若尚未完成，仍可能符合原訂時程。",
      "invalidation": "FedEx 在期限內宣布完成或終止分拆，即推翻年底仍在準備階段的預測。若公司未更新進度，則只能列為待驗證。",
      "claim_ids": ["fdx-sep:decision"]
    },
    {
      "stance": "wait",
      "mechanism": "預期符合美國聯邦所得稅免稅分離資格，無從據此推算母公司可收取的現金。已完成的 10 億美元回購也只提供歷史基準。",
      "target": "FedEx 母公司因分拆而新增的回購",
      "horizon": "2025-12-31",
      "catalyst": "交易文件量化母公司可收取的款項，且資本配置公告說明其用途。",
      "prediction": "基準情境不計入分拆款項帶來的額外回購或每股盈餘增益。即使後續財報再列回購，仍需核對其資金來源。",
      "invalidation": "若公司量化分拆款項並明示用於新增回購，應修正回購假設，再依實際執行時間及股數估算每股盈餘影響。",
      "claim_ids": ["fdx-sep:capital", "fdx-sep:original", "fdx-q2:repurchases", "fdx-q2:original"]
    }
  ],
  "assessment": {
    "thesis": "截至 2024 年 12 月 19 日，FedEx 董事會擬將 FedEx Freight 分拆為獨立上市公司，目標於 18 個月內完成，仍待相關條件及核准。對截至 2025 年底的研究預測，宜維持觀望。現有揭露不足以將分拆換算為母公司現金流入、額外回購或每股盈餘增益。",
    "key_gap": "最影響估算的是分拆後母公司能否取得現金、金額與用途，以及留存業務須承擔哪些成本。",
    "next_check": "優先核對下一份分拆進度公告或交易文件中的預定完成日、待決條件與母公司現金收付條款，再與同期財報的回購用途說明交叉核對。",
    "evidence_limits": [
      {"evidence_id": "fdx-sep:decision", "limit": "18 個月是附條件的完成目標，無法據此指定實際交割日。"},
      {"evidence_id": "fdx-sep:capital", "limit": "未量化母公司實收款，也未指定資金用途。"},
      {"evidence_id": "fdx-sep:original", "limit": "英文摘句只說預期符合免稅資格，最終稅務結果仍待確認。"},
      {"evidence_id": "fdx-q2:repurchases", "limit": "10 億美元是該季已完成的回購金額，資料未提供未來回購承諾。"},
      {"evidence_id": "fdx-q2:original", "limit": "英文摘句與回購摘要來自同一份財報，兩者均未交代回購與分拆的資金關係。"}
    ],
    "public_checks": [
      {"metric": "最新預定完成日、尚待滿足的條件與核准狀態", "source_to_watch": "FedEx 分拆公告與後續交易文件", "window": "自公告後至 2025-12-31", "impact_on_thesis": "若公司明定於研究期內交割，應更新時程情境。正式完成或終止公告可直接檢驗進度預測。", "evidence_ids": ["fdx-sep:decision"]},
      {"metric": "分拆安排載明的母公司現金收付金額與用途", "source_to_watch": "FedEx 分拆交易文件及資本配置公告", "window": "至 2025-12-31 公開的交易條款", "impact_on_thesis": "揭露收付金額後可估算母公司現金影響。若另指定回購用途，才有依據估算額外回購規模。", "evidence_ids": ["fdx-sep:capital", "fdx-sep:original"]},
      {"metric": "各季實際回購金額、股數及公司揭露的資金來源", "source_to_watch": "FedEx 季度財報及回購揭露", "window": "公告後各次財報發布日至 2025-12-31", "impact_on_thesis": "以公告當季的 10 億美元作歷史對照。後續金額變動本身不足以確認分拆貢獻。", "evidence_ids": ["fdx-q2:repurchases", "fdx-q2:original", "fdx-sep:capital"]}
    ],
    "supply_chain": [],
    "trade_opportunities": [
      {"company": "FedEx", "direction": "watch", "earnings_path": "若分拆帶來可供回購的現金，實際買回股份後可能降低加權平均流通股數。在獲利相同的情況下，每股盈餘可因此提高。", "catalyst": "後續交易條款與回購執行情形公開。", "trigger": "公司量化分拆款項、明示回購用途，並揭露足以估算股數變化的執行資料。", "invalidation": "若最終條款顯示母公司無現金收入，或款項全數另有用途，即排除以分拆款項支應回購的投資理由。", "evidence_gap": "缺少交易收付、增量回購股數、分拆後獲利與成本資料，無法判斷每股盈餘淨影響。", "ticker": null, "listing_evidence_id": null, "evidence_ids": ["fdx-sep:capital", "fdx-q2:repurchases"]}
    ]
  }
}
